DROP TABLE IF EXISTS `transacciones`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `transacciones` (
  `id` int NOT NULL AUTO_INCREMENT,
  `tipo` enum('entrada','salida') NOT NULL,
  `monto_total` decimal(10,2) NOT NULL,
  `monto_ganancia` decimal(10,2) NOT NULL DEFAULT '0.00',
  `monto_perdida` decimal(10,2) NOT NULL DEFAULT '0.00',
  `descripcion` text NOT NULL,
  `categoria` enum('empenio','venta','interes','prestamo','gasto','otro') NOT NULL,
  `fecha` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `id_empenio` int DEFAULT NULL,
  `estado` enum('activa','anulada') NOT NULL DEFAULT 'activa',
  `usuarioId` int NOT NULL,
  `empresaId` int NOT NULL,
  `nota` text,
  PRIMARY KEY (`id`),
  KEY `id_empenio` (`id_empenio`),
  KEY `usuario_transaccion_idx` (`usuarioId`),
  KEY `fk_transaccion_empresa` (`empresaId`),
  CONSTRAINT `fk_transaccion_empresa` FOREIGN KEY (`empresaId`) REFERENCES `empresa` (`id`) ON DELETE RESTRICT,
  CONSTRAINT `transacciones_ibfk_1` FOREIGN KEY (`id_empenio`) REFERENCES `empenios` (`idEmpenios`) ON DELETE SET NULL,
  CONSTRAINT `usuario_transaccion` FOREIGN KEY (`usuarioId`) REFERENCES `usuarios` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=350 DEFAULT CHARSET=utf8mb3;
